(function(root){'use strict';
 const rows=[
  {id:'probability',match:/probabil|kebarangkalian|peristiwa|events?|replacement|penggantian|bersandar|independent|dependent|\bp\s*\([^)]{1,80}\)/i,en:['Probability of Combined Events','For equally likely outcomes, P(A) = favourable outcomes / all outcomes. P(A or B) = P(A) + P(B) − P(A and B). In general, P(A and B) = P(A) × P(B given A), when P(A)>0. Use P(A) × P(B) only for independent events. Check replacement and the information given.'],ms:['Kebarangkalian Peristiwa Bergabung','Bagi kesudahan sama mungkin, P(A) = bilangan kesudahan dikehendaki / jumlah kesudahan. P(A atau B) = P(A) + P(B) − P(A dan B). Secara umum, P(A dan B) = P(A) × P(B diberi A), apabila P(A)>0. Gunakan P(A) × P(B) hanya untuk peristiwa tak bersandar. Semak penggantian dan maklumat diberi.']},
  {id:'sets',match:/\bsets?\b|kesatuan|persilangan|union|intersection|venn|semesta|subset|pelengkap|complement|∪|∩|∈|∉|⊆|⊂/i,en:['Operations on Sets','A ∩ B contains elements in both sets. A ∪ B contains elements in A or B, including the intersection; list each element once. The complement of A contains elements in the stated universal set that are not in A. State the universal set first.'],ms:['Operasi Set','A ∩ B mengandungi unsur dalam kedua-dua set. A ∪ B mengandungi unsur dalam A atau B, termasuk persilangannya; senaraikan setiap unsur sekali. Pelengkap A mengandungi unsur dalam set semesta yang dinyatakan tetapi bukan dalam A. Nyatakan set semesta dahulu.']},
  {id:'logic',match:/logic|logik|statement|pernyataan|truth|kebenaran|implika|impli|negat|penafian|kontrapositif|songsang|akas|∧|∨|¬|→|\btrue\b|\bfalse\b|\bbenar\b|\bpalsu\b|\bjika\b.{1,80}\bmaka\b|\bif\b.{1,80}\bthen\b/i,en:['Logical Reasoning','A statement is true or false. Negation reverses its truth value. p and q is true only when both are true. p or q is true when at least one is true. If p, then q is false only when p is true and q is false.'],ms:['Penaakulan Logik','Pernyataan bernilai benar atau palsu. Penafian menukar nilai kebenarannya. p dan q benar hanya apabila kedua-duanya benar. p atau q benar apabila sekurang-kurangnya satu benar. Jika p, maka q palsu hanya apabila p benar dan q palsu.']}
 ];
 const lookup=(id,language='en')=>{const row=rows.find(r=>r.id===id);return row?{id,title:row[language==='ms'?'ms':'en'][0],text:row[language==='ms'?'ms':'en'][1]}:null;};
 const api={entries:rows.map(r=>({id:r.id})),lookup,search:(q,l='en')=>rows.filter(r=>r.match.test(String(q))).map(r=>lookup(r.id,l))};
 if(typeof module!=='undefined')module.exports=api;else root.DCPetKnowledge=api;
})(globalThis);
